@Component("productVariant-handler")
@ProcessingGroup("productVariant-processing-group")
public class ProductVariantEventHandler {
	
	// core constructor
	ProductVariantEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateProductVariantEvent
     */
    @EventHandler
    public void handle( CreateProductVariantEvent event) {
        entityManager.persist(new ProductVariant(event.getProductVariantId(), event.getSku(), event.getBarcode(), event.getTitle(), event.getWeight(), event.getRequiresShipping(), event.getProduct(), event.getPricing(), event.getInventoryItems(), event.getMediaAssets(), event.getSubscriptions(), event.getCartItems(), event.getOrderLines(), event.getWishlistItems(), event.getWeightUnit()));
    }

    /*
     * @param	event UpdateProductVariantEvent
     */
    @EventHandler
    public ProductVariant handle( UpdateProductVariantEvent event) {
    	entityManager.merge(new ProductVariant(event.getProductVariantId(), event.getSku(), event.getBarcode(), event.getTitle(), event.getWeight(), event.getRequiresShipping(), event.getProduct(), event.getPricing(), event.getInventoryItems(), event.getMediaAssets(), event.getSubscriptions(), event.getCartItems(), event.getOrderLines(), event.getWishlistItems(), event.getWeightUnit()));
    }
    
    /*
     * @param	event DeleteProductVariantEvent
     */
    @EventHandler
    public void on( DeleteProductVariantEvent event) {
    	ProductVariant entity = new ProductVariant();
   
    	// ------------------------------------------
    	// apply the ProductVariantId
    	// ------------------------------------------
    	entity.setProductVariantId( event.getProductVariantId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ProductVariantRepository productVariantEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ProductVariantEventHandler.class.getName());

}
